mapper.select:
SELECT 
FROM F2F_DEVICE_STATUS
WHERE CHANNEL = #{channel,jdbcType=VARCHAR}
  AND DEVICE_ID = #{deviceId,jdbcType=VARCHAR}

mapper.update:
UPDATE F2F_DEVICE_STATUS
SET ONLINE_FLAG = '0',
    UPDATE_TMS = SYSTIMESTAMP
WHERE CHANNEL = #{channel,jdbcType=VARCHAR}
  AND DEVICE_ID = #{deviceId,jdbcType=VARCHAR}
  AND ONLINE_FLAG = '1'

mapper.select:
SELECT 
FROM F2F_DEVICE_STATUS
WHERE CHANNEL = #{channel,jdbcType=VARCHAR}

  AND ONLINE_FLAG = #{onlineFlag,jdbcType=VARCHAR}

ORDER BY LAST_HEARTBEAT_TMS DESC
